use sqlx::PgPool;
use uuid::Uuid;

use crate::error::{AppError, AppResult};
use crate::models::opd_visit::{CreateOpdVisit, OpdVisit, UpdateOpdVisit};

pub async fn create(
    pool: &PgPool,
    input: &CreateOpdVisit,
    actor: Option<&str>,
) -> AppResult<OpdVisit> {
    // visit_number is generated by a DB default.
    let visit = sqlx::query_as::<_, OpdVisit>(
        r#"
        INSERT INTO opd_visits
            (patient_id, department_id, doctor_id, appointment_id, visit_type,
             chief_complaint, referred_by, created_by)
        VALUES ($1, $2, $3, $4, COALESCE($5, 'new'), $6, $7, $8)
        RETURNING *
        "#,
    )
    .bind(input.patient_id)
    .bind(input.department_id)
    .bind(input.doctor_id)
    .bind(input.appointment_id)
    .bind(input.visit_type.as_deref())
    .bind(input.chief_complaint.as_deref())
    .bind(input.referred_by.as_deref())
    .bind(actor)
    .fetch_one(pool)
    .await?;
    Ok(visit)
}

pub async fn get(pool: &PgPool, id: Uuid) -> AppResult<OpdVisit> {
    sqlx::query_as::<_, OpdVisit>("SELECT * FROM opd_visits WHERE id = $1")
        .bind(id)
        .fetch_optional(pool)
        .await?
        .ok_or(AppError::NotFound)
}

#[allow(clippy::too_many_arguments)]
pub async fn list(
    pool: &PgPool,
    patient_id: Option<Uuid>,
    doctor_id: Option<Uuid>,
    department_id: Option<Uuid>,
    visit_status: Option<&str>,
    limit: i64,
    offset: i64,
) -> AppResult<Vec<OpdVisit>> {
    let rows = sqlx::query_as::<_, OpdVisit>(
        r#"
        SELECT * FROM opd_visits
        WHERE ($1::uuid IS NULL OR patient_id = $1)
          AND ($2::uuid IS NULL OR doctor_id = $2)
          AND ($3::uuid IS NULL OR department_id = $3)
          AND ($4::text IS NULL OR visit_status = $4)
        ORDER BY visit_date DESC
        LIMIT $5 OFFSET $6
        "#,
    )
    .bind(patient_id)
    .bind(doctor_id)
    .bind(department_id)
    .bind(visit_status)
    .bind(limit)
    .bind(offset)
    .fetch_all(pool)
    .await?;
    Ok(rows)
}

pub async fn update(pool: &PgPool, id: Uuid, input: &UpdateOpdVisit) -> AppResult<OpdVisit> {
    sqlx::query_as::<_, OpdVisit>(
        r#"
        UPDATE opd_visits SET
            department_id   = COALESCE($2, department_id),
            doctor_id       = COALESCE($3, doctor_id),
            visit_type      = COALESCE($4, visit_type),
            visit_status    = COALESCE($5, visit_status),
            chief_complaint = COALESCE($6, chief_complaint),
            referred_by     = COALESCE($7, referred_by)
        WHERE id = $1
        RETURNING *
        "#,
    )
    .bind(id)
    .bind(input.department_id)
    .bind(input.doctor_id)
    .bind(input.visit_type.as_deref())
    .bind(input.visit_status.as_deref())
    .bind(input.chief_complaint.as_deref())
    .bind(input.referred_by.as_deref())
    .fetch_optional(pool)
    .await?
    .ok_or(AppError::NotFound)
}
